use std::thread;
use std::time::Duration;

fn main() {
    // Простой поток
    let handle = thread::spawn(|| {
        for i in 1..=5 {
            println!("Thread: {}", i);
            thread::sleep(Duration::from_millis(100));
        }
    });

    // Основной поток
    for i in 1..=3 {
        println!("Main: {}", i);
        thread::sleep(Duration::from_millis(100));
    }

    // Ждём завершения
    handle.join().unwrap();
}

